import {records,persist,protocolCounts,technicalStates,dimensionNames} from './construction-store.mjs';
export async function renderConstruction(root,ctx){const esc=ctx.esc;root.innerHTML='<p>Cargando registros locales…</p>';try{const [zones,events,protocols,reviews,history,response]=await Promise.all([records('zones'),records('events'),records('protocols'),records('reviews'),records('history'),fetch('door-pilot.json')]);if(!response.ok)throw Error('Piloto de puertas no disponible');const pilot=await response.json(),count=protocolCounts(protocols),latest=(id,d)=>events.filter(e=>e.zoneId===id&&e.dimension===d).at(-1)?.state;root.innerHTML=`<div class="moduleHeading"><div><div class="section-label">CONTROL DE OBRA / DATOS DE ESTE DISPOSITIVO</div><h1>Avances y protocolos</h1><p>Estados por zona. Sin cantidades de producción inferidas.</p></div></div><div class="kpiGrid">${[['Zonas de cielos',zones.filter(z=>z.specialty==='ceilings').length],['Zonas de pavimentos',zones.filter(z=>z.specialty==='floors').length],['Protocolos registrados',count.registered],['Aprobados',count.approved],['Observados',count.observed],['Cielos MEP sin verificar',zones.filter(z=>z.specialty==='ceilings'&&latest(z.id,'mep')!=='Verificado').length]].map(([t,n])=>`<article class="kpi"><span>${t}</span><b>${n}</b></article>`).join('')}</div><p class="dataNote">Total previsto y vencimientos: no documentados. No se calcula cumplimiento ni m² ejecutados. Las zonas pueden ser parciales y sus contornos están pendientes.</p><section class="chartCard"><h3>Control de protocolos</h3><label>Estado técnico<select id="protocolFilter"><option value="">Todos</option>${technicalStates.map(s=>`<option>${s}</option>`).join('')}</select></label><div id="protocolList"></div></section><section class="chartCard"><h3>Avance por zona</h3>${zones.map(z=>`<p><b>${esc(z.roomCode)} · ${esc(z.name)}</b><br>${esc(Object.entries(dimensionNames).filter(([d])=>z.specialty==='floors'?['floor','inspection'].includes(d):d!=='floor').map(([d,n])=>n+': '+(latest(z.id,d)||'Sin registrar')).join(' / '))}</p>`).join('')||'<p>Abre Cielos o Pavimentos y dibuja una zona para registrar avance.</p>'}</section><section class="chartCard"><h3>Revisión de puertas · piloto ARQ 504</h3><p>${pilot.candidates.length} candidatos geométricos. No son un inventario confirmado. Piloto no apto para inventario: el candidato de esta prueba corresponde a equipamiento. Las omisiones no están cuantificadas.</p><label>Mostrar<select id="doorFilter"><option value="">Todos</option><option value="candidate">Pendientes</option><option value="confirmed">Confirmados</option><option value="rejected">Rechazados</option><option value="duplicate">Duplicados</option></select></label><div class="doorBatch"><button data-review="confirmed">Confirmar seleccionados</button><button data-review="rejected">Rechazar seleccionados</button><button data-review="duplicate">Marcar duplicados</button></div><div id="doorGrid" class="documentGrid"></div></section>`;
 const renderProtocols=()=>{const filter=root.querySelector('#protocolFilter').value;root.querySelector('#protocolList').innerHTML=protocols.filter(p=>!filter||p.technical===filter).map(p=>`<form data-protocol="${esc(p.id)}"><h4>${esc(p.number)} · ${esc(p.specialty)}</h4><p>Recintos: ${esc(p.elements.join(', '))}</p><label>Revisión técnica<select name="technical">${technicalStates.map(s=>`<option ${s===p.technical?'selected':''}>${s}</option>`).join('')}</select></label><label>Cierre administrativo<select name="administrative"><option ${p.administrative==='Abierto'?'selected':''}>Abierto</option><option ${p.administrative==='Cerrado'?'selected':''}>Cerrado</option></select></label><label>Responsable<input name="responsible" value="${esc(p.responsible||'')}"></label><label>Observaciones<textarea name="notes">${esc(p.notes)}</textarea></label><button>Guardar revisión</button><details><summary>Historial</summary>${history.filter(h=>h.table==='protocols'&&h.item.id===p.id).map(h=>`<p>${esc(h.at+' · '+h.item.technical+' · '+h.item.administrative)}</p>`).join('')}</details></form>`).join('')||'<p>Sin protocolos en este filtro. Regístralos desde una ficha en Cielos o Pavimentos.</p>';root.querySelectorAll('[data-protocol]').forEach(f=>f.onsubmit=async e=>{e.preventDefault();try{const old=protocols.find(p=>p.id===f.dataset.protocol);await persist('protocols',{...old,...Object.fromEntries(new FormData(f)),at:new Date().toISOString()});await renderConstruction(root,ctx);}catch(e){ctx.toast(e.message);}});};root.querySelector('#protocolFilter').onchange=renderProtocols;renderProtocols();
 const renderDoors=()=>{const state=root.querySelector('#doorFilter').value;root.querySelector('#doorGrid').innerHTML=pilot.candidates.filter(c=>!state||(reviews.find(r=>r.id===c.id)?.status||c.status||'candidate')===state).map(c=>{const review=reviews.find(r=>r.id===c.id),position=review?.position||c.position;return `<article class="doorCandidate"><label><input type="checkbox" data-candidate="${esc(c.id)}"> ${esc(c.id.slice(-8))} · ${esc(review?.status||c.status||'candidate')}</label><div class="doorPreview"><img src="${esc(c.preview)}" alt="Contexto documental de puerta candidata"><i style="left:${(position[0]-c.previewBounds[0])/(c.previewBounds[2]-c.previewBounds[0])*100}%;top:${(position[1]-c.previewBounds[1])/(c.previewBounds[3]-c.previewBounds[1])*100}%"></i></div><small>ARQ 504 · ${esc(c.revision)} · página 1. Prioridad heurística 0,55; no es probabilidad.</small><a href="source/${esc(c.filename)}" target="_blank" rel="noopener">PDF fuente ↗</a><form data-position="${esc(c.id)}"><label>X PDF<input name="x" type="number" step="any" value="${position[0]}" required></label><label>Y PDF<input name="y" type="number" step="any" value="${position[1]}" required></label><label>Recinto verificado<input name="roomCode" value="${esc(review?.roomCode||'')}" placeholder="Sin asociación confirmada"></label><p class="dataNote">Etiquetas próximas, sin validar: ${esc(c.roomSuggestions.map(r=>r.code).join(', '))}</p><button>Guardar corrección</button></form></article>`;}).join('');root.querySelectorAll('[data-position]').forEach(f=>f.onsubmit=async e=>{e.preventDefault();try{const values=Object.fromEntries(new FormData(f)),x=Number(values.x),y=Number(values.y),c=pilot.candidates.find(c=>c.id===f.dataset.position);if(!Number.isFinite(x)||!Number.isFinite(y)||x<c.previewBounds[0]||y<c.previewBounds[1]||x>c.previewBounds[2]||y>c.previewBounds[3])throw Error('La corrección debe quedar dentro del recorte mostrado');if(values.roomCode&&!ctx.data().rooms.some(r=>r.code===values.roomCode))throw Error('Código de recinto no documentado');await persist('reviews',{...c,...reviews.find(r=>r.id===c.id),id:c.id,position:[x,y],roomCode:values.roomCode,at:new Date().toISOString()});await renderConstruction(root,ctx);}catch(e){ctx.toast(e.message);}});};root.querySelector('#doorFilter').onchange=renderDoors;renderDoors();root.querySelectorAll('[data-review]').forEach(b=>b.onclick=async()=>{try{const ids=[...root.querySelectorAll('[data-candidate]:checked')].map(e=>e.dataset.candidate);if(!ids.length)throw Error('Selecciona al menos un candidato');for(const id of ids){const c=pilot.candidates.find(c=>c.id===id);await persist('reviews',{...c,...reviews.find(r=>r.id===id),id,status:b.dataset.review,at:new Date().toISOString()});}await renderConstruction(root,ctx);}catch(e){ctx.toast(e.message);}});
 }catch(e){root.textContent=e.message;}}
